import {poiExtent,walkerCamera,walkerMessageValid} from './terrain-camera.js';
// Uses the public Mars layer configuration documented by Esri/explore-mars.
// Custom application code; no Esri application source is bundled here.
const ASTRONAUT='data:image/svg+xml;utf8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 46"><g stroke="#0c0b08" stroke-width="1.4" stroke-linejoin="round"><rect x="5" y="15" width="22" height="18" rx="5" fill="#d5c7a8"/><rect x="9" y="15" width="14" height="17" rx="5" fill="#f4f1ec"/><rect x="2" y="17" width="6" height="14" rx="3" fill="#f4f1ec"/><rect x="24" y="17" width="6" height="14" rx="3" fill="#f4f1ec"/><rect x="10" y="31" width="5" height="11" rx="2" fill="#f4f1ec"/><rect x="17" y="31" width="5" height="11" rx="2" fill="#f4f1ec"/><rect x="9" y="40" width="7" height="4" rx="2" fill="#85785c"/><rect x="16" y="40" width="7" height="4" rx="2" fill="#85785c"/><circle cx="16" cy="9" r="8" fill="#f4f1ec"/><ellipse cx="16" cy="9.5" rx="5.6" ry="4.6" fill="#e0a11a"/></g><ellipse cx="14" cy="7.8" rx="2" ry="1.2" fill="#ffc23d" opacity=".8"/><rect x="13" y="19" width="6" height="3" rx="1" fill="#ffb007" stroke="#0c0b08" stroke-width=".8"/></svg>');
(()=>{const status=document.getElementById('status');let view,graphics,poiLayer,walkLayer,hazardLayer,Graphic,Extent,latest,lastZ;
 const sr={wkid:104971};
 function sync(data){latest=data;if(!graphics)return;graphics.removeAll();poiLayer.removeAll();hazardLayer.removeAll();
  if(data.showHazards)for(const h of (Array.isArray(data.hazards)?data.hazards:[]).slice(0,1200)){const ring=h&&h.ring;if(!Array.isArray(ring)||ring.length<4)continue;const steep=(+h.gt||20)>=20;hazardLayer.add(new Graphic({geometry:{type:'polygon',rings:[ring],spatialReference:sr},symbol:{type:'simple-fill',color:steep?[255,59,59,.42]:[255,191,31,.26],outline:{color:steep?[255,90,60,.95]:[255,200,60,.7],width:1}},popupTemplate:{title:steep?'Steep ground (over 20°)':'Moderate slope (over 10°)',content:'Slope in the 20 m CTX DEM (Mangold et al. 2021). Rocks and sand are not modelled.'}}))}
  if(data.showRegions)for(const r of (Array.isArray(data.regions)?data.regions:[]).slice(0,10)){if(!Array.isArray(r.ring)||r.ring.length<3)continue;hazardLayer.add(new Graphic({geometry:{type:'polygon',rings:[r.ring.concat([r.ring[0]])],spatialReference:sr},symbol:{type:'simple-fill',color:[61,255,122,.08],outline:{color:[61,255,122,.9],width:2,style:'dash'}},popupTemplate:{title:String(r.name).slice(0,60),content:'Region outline: convex hull of this region\'s photographed points.'}}))}
  for(const p of data.pois||[])poiLayer.add(new Graphic({geometry:{type:'point',x:p.coord[0],y:p.coord[1],spatialReference:sr},attributes:{id:p.id,name:p.name,description:p.description,sol:p.sol,tasks:p.plannedTasks||'Not in selected mission'},symbol:{type:'point-3d',symbolLayers:[{type:'icon',size:11,resource:{primitive:'circle'},material:{color:'#ffd987'},outline:{color:'#132815',size:1.5}}]},popupTemplate:{title:'{name}',content:'{description}<br><br>Mastcam-Z · Sol {sol}<br>Mission tasks: {tasks}',actions:[{id:'panorama',title:'Open panorama',className:'esri-icon-media'}]}}));
  if(data.route?.length>1)graphics.add(new Graphic({geometry:{type:'polyline',paths:[data.route.map(c=>c.slice(0,2))],spatialReference:sr},symbol:{type:'simple-line',color:'#eed7a5',width:3},popupTemplate:{title:'Selected mission route',content:'Historical rover corridor; not a certified EVA route.'}}));
  if(data.base)poiLayer.add(new Graphic({geometry:{type:'point',x:data.base.longitude,y:data.base.latitude,spatialReference:sr},symbol:{type:'point-3d',symbolLayers:[{type:'icon',size:15,resource:{primitive:'square'},material:{color:'#ffc23d'},outline:{color:'#132815',size:2}}]},popupTemplate:{title:'Martian Base',content:'Fictional departure and return point.'+(data.base.plannedTasks?' Planned activity: '+data.base.plannedTasks+' — hypothetical rover rendezvous.':'')}}));
  for(const c of data.custom||[])poiLayer.add(new Graphic({geometry:{type:'point',x:c.coord[0],y:c.coord[1],spatialReference:sr},attributes:{id:null,customId:c.id,name:c.name},symbol:{type:'point-3d',symbolLayers:[{type:'icon',size:12,resource:{primitive:'kite'},material:{color:'#ffb007'},outline:{color:'#132815',size:1.5}}]},popupTemplate:{title:'{name}',content:'Custom point of interest (saved in this browser).'}}));
  if(data.pin)poiLayer.add(new Graphic({geometry:{type:'point',x:data.pin.lon,y:data.pin.lat,spatialReference:sr},attributes:{id:null,name:'Selected point'},symbol:{type:'point-3d',symbolLayers:[{type:'icon',size:14,resource:{primitive:'cross'},material:{color:'#3dff6e'},outline:{color:'#3dff6e',size:2}}]}}));
  if(data.camera){if(data.camera.global)view.goTo({position:{x:77.42,y:18.46,z:12000000,spatialReference:sr},heading:0,tilt:0}).catch(()=>{});else framePOIs(false)}
 }
 async function framePOIs(animate){if(!view)return;await view.goTo({target:new Extent(poiExtent(latest?.pois||[],latest?.base)),heading:0,tilt:20},{animate:animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches,duration:4200}).catch(()=>{})}

 let walkerGraphic,trailGraphic,lastMode=null;
 async function fitTop(){if(!view||!Extent)return;const pts=(latest?.route||[]).map(c=>({coord:c}));await view.goTo({target:new Extent(poiExtent(pts,latest?.base)),heading:0,tilt:0},{animate:false}).catch(()=>{})}
 function walker(m){if(!walkLayer)return;
  if(m.clear){walkLayer.removeAll();walkerGraphic=trailGraphic=null;lastMode=null;return}
  if(!walkerMessageValid(m))return;const c=m.coord;if(Number.isFinite(c[2]))lastZ=c[2];
  if(Array.isArray(m.trail)&&m.trail.length>1){if(trailGraphic)walkLayer.remove(trailGraphic);trailGraphic=new Graphic({geometry:{type:'polyline',paths:[m.trail.map(t=>[t[0],t[1]])],spatialReference:sr},symbol:{type:'simple-line',color:'#ffb007',width:3}});walkLayer.add(trailGraphic)}
  if(walkerGraphic)walkLayer.remove(walkerGraphic);
  walkerGraphic=new Graphic({geometry:{type:'point',x:c[0],y:c[1],spatialReference:sr},symbol:{type:'point-3d',symbolLayers:[{type:'icon',size:38,anchor:'bottom',resource:{href:ASTRONAUT}}]}});walkLayer.add(walkerGraphic);
  if(m.mode!==lastMode){lastMode=m.mode;if(m.mode==='overhead')fitTop()}
  const cam=walkerCamera(m.mode,c,m.heading,lastZ);if(cam&&view)view.goTo(cam,{animate:false}).catch(()=>{});
 }
 addEventListener('message',async e=>{if(e.origin!==location.origin||e.source!==parent||!['marswalk-terrain','marswalk-flight','marswalk-walker'].includes(e.data?.type))return;if(e.data.type==='marswalk-walker'){walker(e.data);return}if(e.data.type==='marswalk-flight'){if(Array.isArray(e.data.focus)&&e.data.focus.length===2&&e.data.focus.every(Number.isFinite)){try{await view.goTo({target:{type:'point',x:e.data.focus[0],y:e.data.focus[1],spatialReference:sr},tilt:55,scale:9000},{duration:1100})}catch{}}else await framePOIs(e.data.animate);parent.postMessage({type:'marswalk-flight-done',requestId:e.data.requestId},location.origin)}else sync(e.data)});
 const timeout=setTimeout(()=>status.textContent='Still loading terrain. You can return to the 2D map.',20000);
 if(!window.require){clearTimeout(timeout);return}
 require(['esri/Map','esri/Basemap','esri/views/SceneView','esri/layers/TileLayer','esri/layers/ElevationLayer','esri/layers/GraphicsLayer','esri/Graphic','esri/widgets/Popup','esri/geometry/Extent'],(Map,Basemap,SceneView,TileLayer,ElevationLayer,GraphicsLayer,G,Popup,E)=>{
  Graphic=G;Extent=E;graphics=new GraphicsLayer({elevationInfo:{mode:'on-the-ground'}});poiLayer=new GraphicsLayer({elevationInfo:{mode:'relative-to-ground',offset:15}});walkLayer=new GraphicsLayer({elevationInfo:{mode:'relative-to-ground',offset:4}});hazardLayer=new GraphicsLayer({elevationInfo:{mode:'on-the-ground'}});
  const imagery=new TileLayer({portalItem:{id:'1efb16809db84f0c892b9b0662dab0c8'}}),elevation=new ElevationLayer({url:'https://astro.arcgis.com/arcgis/rest/services/OnMars/MDEM200M/ImageServer'});
  const detail=new TileLayer({portalItem:{id:'c1c4c750a2154842ae523c984cc14fa5'},visible:true});document.getElementById('detail').onchange=e=>detail.visible=e.target.checked;
  const map=new Map({basemap:new Basemap({baseLayers:[imagery,detail]}),ground:{layers:[elevation]},layers:[hazardLayer,graphics,poiLayer,walkLayer]});
  view=new SceneView({container:'scene',map,spatialReference:sr,qualityProfile:'high',popup:new Popup({dockEnabled:false}),camera:{position:{x:77.42,y:18.46,z:12000000,spatialReference:sr},tilt:0},environment:{lighting:{type:'virtual'}}});
  view.popup.on('trigger-action',e=>{if(e.action.id==='panorama'){const id=view.popup.selectedFeature?.attributes?.id;if(Number.isInteger(id))parent.postMessage({type:'marswalk-open-panorama',id},location.origin)}});
  view.on('click',async e=>{try{const hits=await view.hitTest(e,{include:poiLayer});if(hits.results.some(r=>r.graphic?.attributes?.id!=null||r.graphic?.attributes?.customId))return;const p=view.toMap(e);if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y))parent.postMessage({type:'marswalk-map-click',lon:p.x,lat:p.y,z:Number.isFinite(p.z)?p.z:null,sx:Number.isFinite(e.x)?e.x:null,sy:Number.isFinite(e.y)?e.y:null},location.origin)}catch{}});
  let hoverBusy=false,lastHover=0;view.on('pointer-move',async e=>{if(hoverBusy||view.interacting||performance.now()-lastHover<200)return;hoverBusy=true;lastHover=performance.now();try{const hits=await view.hitTest(e,{include:poiLayer}),hit=hits.results.find(r=>r.graphic?.attributes?.id!=null);if(hit&&view.popup.selectedFeature?.attributes?.id!==hit.graphic.attributes.id)view.openPopup({features:[hit.graphic],location:hit.mapPoint})}catch{}finally{hoverBusy=false}});
  Promise.all([view.when(),elevation.load(),imagery.load()]).then(()=>{clearTimeout(timeout);status.textContent='Esri terrain · elevation detail varies';if(latest)sync(latest);parent.postMessage({type:'marswalk-terrain-ready'},location.origin)}).catch(()=>{clearTimeout(timeout);status.textContent='Terrain could not load. Use the 2D map.'});
 },()=>{clearTimeout(timeout);status.textContent='Esri renderer unavailable. Use the 2D map.';parent.postMessage({type:'marswalk-terrain-failed'},location.origin)});
})();
